public class ValidatorsTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object okOrNull(Validator v, String s) {
        return v == null ? null : v.ok(s);
    }

    public static void main(String[] args) {
        Validator min3 = Validators.minLength(3);
        check("minLength(3) accepts \"abcd\"", true, okOrNull(min3, "abcd"));
        check("minLength(3) accepts \"abc\" (boundary)", true, okOrNull(min3, "abc"));
        check("minLength(3) rejects \"ab\"", false, okOrNull(min3, "ab"));

        Validator digit = Validators.containsDigit();
        check("containsDigit accepts \"a1b\"", true, okOrNull(digit, "a1b"));
        check("containsDigit rejects \"abc\"", false, okOrNull(digit, "abc"));
        check("containsDigit rejects \"\"", false, okOrNull(digit, ""));

        Validator combo = Validators.allOf(Validators.minLength(3), Validators.containsDigit());
        check("allOf accepts \"ab1\"", true, okOrNull(combo, "ab1"));
        check("allOf rejects \"abc\" (no digit)", false, okOrNull(combo, "abc"));
        check("allOf rejects \"a1\" (too short)", false, okOrNull(combo, "a1"));

        check("allOf() with no validators accepts anything", true, okOrNull(Validators.allOf(), "x"));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

