interface Validator {
    boolean ok(String s);
}

public class Validators {

    public static Validator minLength(int n) {
        return s -> s.length() >= n;
    }

    public static Validator containsDigit() {
        return s -> {
            for (int i = 0; i < s.length(); i++) {
                if (Character.isDigit(s.charAt(i))) {
                    return true;
                }
            }
            return false;
        };
    }

    public static Validator allOf(Validator... vs) {
        return s -> {
            for (Validator v : vs) {
                if (!v.ok(s)) {
                    return false;
                }
            }
            return true;
        };
    }
}
